import csv
import io
import re
from collections import Counter
from typing import Any, Dict, List


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    source = raw_csv
    if source.startswith("\ufeff"):
        source = source[1:]

    try:
        reader = csv.reader(
            io.StringIO(source, newline=""),
            delimiter=",",
            quotechar='"',
            escapechar=None,
            doublequote=True,
            skipinitialspace=True,
            strict=False,
        )
        parsed = [list(row) for row in reader]
    except csv.Error:
        reader = csv.reader(
            io.StringIO(source, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=True,
            strict=False,
        )
        parsed = [list(row) for row in reader]

    def clean_row(row: List[str]) -> List[str]:
        return [value.strip() for value in row]

    cleaned = [clean_row(row) for row in parsed]
    nonempty_indices = [
        index for index, row in enumerate(cleaned)
        if any(value != "" for value in row)
    ]

    if not nonempty_indices:
        return {"columns": [], "rows": []}

    date_like = re.compile(
        r"^\s*\d{1,4}\s*[-/]\s*\d{1,2}\s*[-/]\s*\d{1,4}"
    )

    header_index = nonempty_indices[0]
    for position, index in enumerate(nonempty_indices[:-1]):
        following = cleaned[nonempty_indices[position + 1]]
        candidate = cleaned[index]
        if (
            len(candidate) >= 2
            and following
            and date_like.search(following[0] or "")
            and any(re.search(r"[A-Za-z]", value) for value in candidate)
        ):
            header_index = index
            break

    header = cleaned[header_index]
    if not header:
        return {"columns": [], "rows": []}

    width = len(header)
    rows: List[List[str]] = []

    for row in cleaned[header_index + 1:]:
        if len(row) < width:
            rows.append(row + [""] * (width - len(row)))
        elif len(row) > width:
            rows.append(row[:width - 1] + [",".join(row[width - 1:])])
        else:
            rows.append(row)

    return {"columns": header, "rows": rows}
